<script setup>
import { ref, computed, watch, onMounted, onUnmounted } from 'vue'
const sections=[{id:'tv',name:'TV Shows',eyebrow:'THE EPISODIC UNIVERSE',heading:'Series worth staying up for.'},{id:'anime',name:'Anime',eyebrow:'BEYOND IMAGINATION',heading:'A world without limits.'},{id:'movies',name:'Films',eyebrow:'THE ART OF STORYTELLING',heading:'Timeless stories, beautifully told.'},{id:'saved',name:'My List',eyebrow:'YOUR PRIVATE COLLECTION',heading:'The stories you love.'}]
const active=ref('tv'),shows=ref([]),loading=ref(false),error=ref(''),search=ref(''),genre=ref('All'),sort=ref('featured'),page=ref(1),detail=ref(null),playing=ref(false),mobileMenu=ref(false),saved=ref([])
try{saved.value=JSON.parse(localStorage.getItem('cinex_saved')||'[]')}catch{saved.value=[]}
const section=computed(()=>sections.find(s=>s.id===active.value))
const categories=computed(()=>['All',...new Set(shows.value.flatMap(x=>x.genres))].slice(0,22))
const results=computed(()=>{let list=shows.value.filter(x=>(genre.value==='All'||x.genres.includes(genre.value))&&[x.title,x.description,x.genres.join(' ')].join(' ').toLowerCase().includes(search.value.toLowerCase()));if(sort.value==='rating')list=[...list].sort((a,b)=>(b.rating||0)-(a.rating||0));if(sort.value==='newest')list=[...list].sort((a,b)=>(parseInt(b.year)||0)-(parseInt(a.year)||0));if(sort.value==='az')list=[...list].sort((a,b)=>a.title.localeCompare(b.title));return list})
const featured=computed(()=>shows.value.find(x=>x.backdrop&&x.image)||shows.value.find(x=>x.image))
const count=computed(()=>results.value.length)
const clean=s=>(s||'').replace(/<[^>]+>/g,'').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'")
const tv=x=>({key:'tv-'+x.id,title:x.name,description:clean(x.summary),image:x.image?.medium||x.image?.original||'',backdrop:x.image?.original||'',genres:x.genres||[],rating:x.rating?.average||0,year:x.premiered?.slice(0,4)||'—',duration:x.runtime?x.runtime+' min':'',kind:'TV SERIES',link:x.officialSite||x.url||'',trailer:'',subtitle:x.network?.name||x.webChannel?.name||''})
const anime=x=>({key:'anime-'+x.mal_id,title:x.title_english||x.title,description:clean(x.synopsis),image:x.images?.webp?.large_image_url||x.images?.jpg?.large_image_url||'',backdrop:x.images?.webp?.large_image_url||'',genres:(x.genres||[]).map(g=>g.name),rating:x.score||0,year:String(x.year||x.aired?.from?.slice(0,4)||'—'),duration:x.episodes?x.episodes+' episodes':'',kind:'ANIME',link:x.url||'',trailer:x.trailer?.embed_url||'',subtitle:x.studios?.map(s=>s.name).join(' · ')||''})
const film=x=>({key:'film-'+x.id,title:x.title,description:clean(x.description),image:x.image||'',backdrop:x.movie_banner||x.image||'',genres:['Animation','Fantasy'],rating:x.rt_score?Number(x.rt_score)/10:0,year:x.release_date||'—',duration:x.running_time?x.running_time+' min':'',kind:'STUDIO GHIBLI',link:'',trailer:'',subtitle:'Directed by '+x.director})
let serial=0
async function load(){const current=++serial;loading.value=true;error.value='';shows.value=[];try{let data;if(active.value==='saved'){data=[...saved.value]}else{const url=active.value==='tv'?'https://api.tvmaze.com/shows?page=0':active.value==='anime'?'https://api.jikan.moe/v4/top/anime?limit=25':'https://ghibliapi.vercel.app/films';const res=await fetch(url);if(!res.ok)throw Error('HTTP '+res.status);const raw=await res.json();data=active.value==='tv'?raw.slice(0,160).map(tv):active.value==='anime'?raw.data.map(anime):raw.map(film)}if(current===serial)shows.value=data}catch(e){if(current===serial)error.value='The collection is temporarily unavailable. '+e.message}finally{if(current===serial)loading.value=false}}
function switchTo(id){active.value=id;search.value='';genre.value='All';sort.value='featured';page.value=1;mobileMenu.value=false;detail.value=null;window.scrollTo({top:0,behavior:'smooth'})}
watch(active,load);watch([search,genre,sort],()=>page.value=1)
watch(saved,v=>{localStorage.setItem('cinex_saved',JSON.stringify(v));if(active.value==='saved')shows.value=[...v]},{deep:true})
const isSaved=item=>saved.value.some(x=>x.key===item.key)
function toggleSaved(item){saved.value=isSaved(item)?saved.value.filter(x=>x.key!==item.key):[...saved.value,item]}
function openDetail(item){detail.value=item;playing.value=false;document.body.style.overflow='hidden'}
function closeDetail(){detail.value=null;playing.value=false;document.body.style.overflow=''}
function escape(e){if(e.key==='Escape')closeDetail()}
function scrollToCollection(){document.getElementById('collection')?.scrollIntoView({behavior:'smooth'})}
onMounted(()=>{load();window.addEventListener('keydown',escape)})
onUnmounted(()=>{window.removeEventListener('keydown',escape);document.body.style.overflow=''})
</script>
<template>
<div class="site">
<header class="header"><a class="logo" href="#" @click.prevent="switchTo('tv')" aria-label="CINEX home"><span class="logo-mark"><span>▶</span></span>CINE<span class="logo-accent">X</span><i>.</i></a><nav class="desktop-nav" aria-label="Primary navigation"><button v-for="s in sections" :key="s.id" @click="switchTo(s.id)" :class="{selected:active===s.id}">{{s.name}}<span v-if="s.id==='saved'&&saved.length" class="nav-count">{{saved.length}}</span></button></nav><div class="header-right"><span class="signature">A PSMY ORIGINAL</span><button class="menu-toggle" aria-label="Toggle menu" :aria-expanded="mobileMenu" @click="mobileMenu=!mobileMenu">☰</button></div></header>
<nav v-if="mobileMenu" class="mobile-nav" aria-label="Mobile navigation"><button v-for="s in sections" :key="s.id" @click="switchTo(s.id)">{{s.name}}</button></nav>
<main>
<section class="hero" :style="featured?.backdrop?{'--hero-bg':'url('+featured.backdrop+')'}:{}">
<div class="hero-backdrop"></div><div class="hero-content"><div class="hero-overline"><span class="live-dot"></span> THE NEXT CHAPTER IN ENTERTAINMENT <span class="hero-rule"></span> VOL. 01 / 2026</div><div class="hero-center"><div class="hero-label"><span class="tiny-star">✳</span> CURATED FOR THE CURIOUS</div><h1>NOT JUST<br>ANOTHER <span class="gradient-word">STORY.</span></h1><p>Great stories don't just entertain. They stay with you. Explore exceptional television, anime and film — all in one extraordinary place.</p><div class="hero-buttons"><button class="button filled" @click="scrollToCollection">Explore the collection <span>↗</span></button><button class="button outlined" v-if="featured" @click="openDetail(featured)">Editor's pick <span>↗</span></button></div></div><div class="hero-foot"><span>SCROLL TO DISCOVER <b>↓</b></span><span>DISCOVER / SAVE / REPEAT</span></div></div><div class="hero-vertical">CINEX — BEYOND THE SCREEN</div></section>
<div class="ticker" aria-hidden="true"><div>STORIES THAT STAY WITH YOU <span>✳</span> ANIME <span>✳</span> CINEMA <span>✳</span> TELEVISION <span>✳</span> DISCOVER SOMETHING NEW <span>✳</span></div></div>
<section class="intro"><div class="intro-index">01 / THE EXPERIENCE</div><div><p class="intro-overline">WELCOME TO YOUR NEXT OBSESSION</p><h2>GOOD STORIES.<br><em>GREAT DISCOVERIES.</em></h2></div><p class="intro-desc">An intentionally curated space to find the stories worth your time. No noise. Just cinema, animation and television worth talking about.</p></section>
<section class="collection" id="collection"><div class="collection-top"><div><div class="section-kicker"><span class="diamond">◆</span> {{section.eyebrow}}</div><h2>{{section.heading}}</h2><p>Handpicked discoveries from the world of {{active==='tv'?'television':active==='anime'?'anime':active==='movies'?'animated cinema':'your saved favorites'}}.</p></div><div class="collection-number"><span>{{String(count).padStart(2,'0')}}</span><small>TITLES AVAILABLE</small></div></div>
<div class="category-tabs" role="group" aria-label="Choose a collection"><button v-for="(s,i) in sections" :key="s.id" @click="switchTo(s.id)" :class="{current:active===s.id}"><span class="tab-index">0{{i+1}}</span>{{s.name}}<span class="tab-arrow">↗</span></button></div>
<div class="toolbar"><label class="search-box"><span>⌕</span><input v-model="search" type="search" placeholder="Search stories, titles, genres..." aria-label="Search stories"></label><label class="select-box"><span>GENRE</span><select v-model="genre" aria-label="Filter by genre"><option v-for="g in categories" :key="g">{{g}}</option></select></label><label class="select-box"><span>SORT</span><select v-model="sort" aria-label="Sort titles"><option value="featured">Featured</option><option value="rating">Top rated</option><option value="newest">Newest</option><option value="az">A — Z</option></select></label><button class="reload" @click="load" :disabled="loading" aria-label="Refresh collection">↻</button></div>
<div v-if="loading" class="poster-grid" aria-label="Loading stories"><div class="skeleton" v-for="n in 10" :key="n"></div></div>
<div v-else-if="error" class="empty-state" role="alert"><span class="empty-symbol">↻</span><h3>We hit a little intermission.</h3><p>{{error}}</p><button class="button filled" @click="load">Try again ↗</button></div>
<div v-else-if="!results.length" class="empty-state"><span class="empty-symbol">◇</span><h3>Nothing in this scene.</h3><p>{{active==='saved'?'Save a few titles to start your collection.':'Try a different search or genre.'}}</p><button class="button filled" @click="search='';genre='All'">Reset filters ↗</button></div>
<template v-else><div class="poster-grid"><article v-for="(item,i) in results.slice(0,page*20)" :key="item.key" class="poster-card"><button class="poster-image" @click="openDetail(item)" :aria-label="'See details for '+item.title"><img v-if="item.image" :src="item.image" :alt="'Poster of '+item.title" loading="lazy"><span v-else class="poster-fallback">CINEX</span><span class="poster-gradient"></span><span class="poster-cta">EXPLORE STORY <b>↗</b></span><span class="poster-type">{{item.kind}}</span></button><div class="poster-info"><div class="poster-topline"><span>{{item.year}}</span><span v-if="item.rating" class="rating">★ {{item.rating.toFixed(1)}}</span></div><h3>{{item.title}}</h3><div class="poster-bottom"><span>{{item.genres.slice(0,2).join(' / ')||'Entertainment'}}</span><button @click="toggleSaved(item)" :aria-label="isSaved(item)?'Remove '+item.title+' from watchlist':'Save '+item.title" class="save-button" :class="{isSaved:isSaved(item)}">{{isSaved(item)?'♥':'♡'}}</button></div></div></article></div><div class="pagination" v-if="results.length>page*20"><button class="button outlined" @click="page++">LOAD MORE STORIES <span>↓</span></button></div></template>
</section>
<section class="manifesto"><div class="manifesto-art">✳</div><div class="manifesto-content"><div class="section-kicker">✦ THE CINEX PHILOSOPHY</div><h2>THE BEST STORIES<br>ARE <em>FELT.</em><br>NOT JUST SEEN.</h2><p>From the first frame to the final credits, find something that makes you feel something.</p><button class="button filled" @click="scrollToCollection">Find your next favorite ↗</button></div><span class="manifesto-watermark">CINEX</span></section>
</main><footer class="footer"><div class="footer-top"><div><a href="#" class="logo" @click.prevent="switchTo('tv')">CINE<span class="logo-accent">X</span><i>.</i></a><p>BEYOND THE SCREEN.<br>MADE FOR THE STORIES THAT MATTER.</p></div><div class="footer-links"><button @click="switchTo('tv')">TV Shows</button><button @click="switchTo('anime')">Anime</button><button @click="switchTo('movies')">Films</button><button @click="switchTo('saved')">My List</button></div></div><div class="footer-bottom"><span>© 2026 CINEX. DEVELOPED BY PSMY.</span><span>POWERED BY TVMAZE / JIKAN / GHIBLI API</span><span>CRAFTED WITH PURPOSE ✳</span></div><p class="disclaimer">CINEX is an independent discovery project. Artwork and content belong to their respective rights holders. Full films and episodes are not hosted here.</p></footer>
<div v-if="detail" class="modal-overlay" @click.self="closeDetail"><section class="detail-modal" role="dialog" aria-modal="true" :aria-label="detail.title"><button class="modal-close" @click="closeDetail" aria-label="Close dialog">✕</button><div class="detail-banner" :style="detail.backdrop?{'background-image':'linear-gradient(0deg,#18111e,transparent 90%),url('+detail.backdrop+')'}:{}"></div><div class="detail-body"><span class="section-kicker">✳ {{detail.kind}} / {{detail.year}}</span><h2>{{detail.title}}</h2><div class="detail-tags"><span v-if="detail.rating">★ {{detail.rating.toFixed(1)}} / 10</span><span v-if="detail.duration">{{detail.duration}}</span><span v-for="g in detail.genres.slice(0,3)" :key="g">{{g}}</span></div><p class="synopsis">{{detail.description||'Synopsis is not available for this title.'}}</p><p v-if="detail.subtitle" class="detail-subtitle">{{detail.subtitle}}</p><div class="detail-buttons"><button class="button filled" @click="toggleSaved(detail)">{{isSaved(detail)?'♥ Saved to My List':'♡ Add to My List'}}</button><button v-if="detail.trailer" class="button outlined" @click="playing=!playing">{{playing?'Hide trailer':'▶ Watch official trailer'}}</button><a v-if="detail.link" :href="detail.link" target="_blank" rel="noopener noreferrer" class="button outlined">Visit official listing ↗</a></div><div v-if="playing&&detail.trailer" class="video-player"><iframe :src="detail.trailer" title="Official anime trailer" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div><p class="video-disclaimer">Video playback is available only when a licensed official trailer is provided by the data source. CINEX does not stream copyrighted full episodes or movies.</p></div></section></div>
</div>
</template>